mapper.update:
DECLARE
    v_count NUMBER;
BEGIN
    SELECT COUNT(*)
      INTO v_count
      FROM USER_TAB_COLUMNS
     WHERE TABLE_NAME = 'EVENTS'
       AND COLUMN_NAME = 'EVENT_TYPE';

    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (EVENT_TYPE VARCHAR2(30) DEFAULT ''APPOINTMENT'' NOT NULL)';
    END IF;
END;

DECLARE
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM USER_TABLES WHERE TABLE_NAME = 'EVENT_ATTENDEES';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'CREATE TABLE EVENT_ATTENDEES (EA_ID NUMBER(20) NOT NULL, EVENT_ID NUMBER(10) NOT NULL, USER_ID NUMBER(10) NOT NULL, ST_CODE VARCHAR2(10) DEFAULT ''WT'' NOT NULL, CREATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT PK_EVENT_ATTENDEES PRIMARY KEY (EA_ID), CONSTRAINT UK_EVENT_ATTENDEE_USER UNIQUE (EVENT_ID, USER_ID), CONSTRAINT FK_EA_EVENT FOREIGN KEY (EVENT_ID) REFERENCES EVENTS(EVENT_ID) ON DELETE CASCADE, CONSTRAINT FK_EA_USER FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID))';
    END IF;

    SELECT COUNT(*) INTO v_count FROM USER_SEQUENCES WHERE SEQUENCE_NAME = 'SEQ_EA_ID';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_EA_ID START WITH 1 INCREMENT BY 1 NOCACHE';
    END IF;
END;

mapper.select:
SELECT t.TASK_ID AS id, t.TASK_ID AS taskId, t.TITLE AS title, TO_CHAR(t.START_AT, 'YYYY-MM-DD HH24:MI:SS') AS startDt, TO_CHAR(t.END_AT, 'YYYY-MM-DD HH24:MI:SS') AS endDt, 'TASK' AS itemType, t.ASSIGNEE_ID AS userId, t.PROJ_ID AS projId, p.WS_ID AS wsId, '#8b63f6' AS color, 'TASK' AS eventType, NVL(t.STATUS, 'TODO') AS status, CASE WHEN t.ALL_DAY_YN = 'N' THEN 'TIME' ELSE 'NONE' END AS startTimeSlot, CASE WHEN t.ALL_DAY_YN = 'N' THEN 'TIME' ELSE 'NONE' END AS endTimeSlot, 'N' AS isPrivate, t.ALL_DAY_YN AS allDay, w.WS_NAME AS wsName, p.PROJ_NAME AS projName, w.WS_NAME AS projectWorkspaceName, p.PROJ_SCOPE AS projectScope, 'TASK' AS projectItemKind, w.WS_IMAGE_PATH AS wsImagePath, t.ASSIGNEE_ID AS assigneeUserId, CASE WHEN NVL(UPPER(p.PROJ_SCOPE), CASE WHEN p.WS_ID IS NULL THEN 'PERSONAL' ELSE 'GROUP' END) = 'GROUP' AND NVL(wmp.USE_ACCOUNT_PROFILE, 'Y') = 'N' THEN NVL(wmp.DISPLAY_NAME, u.USER_NAME) ELSE u.USER_NAME END AS assigneeName, NVL(wmp.CONTACT_EMAIL, u.EMAIL) AS assigneeEmail, CASE WHEN NVL(UPPER(p.PROJ_SCOPE), CASE WHEN p.WS_ID IS NULL THEN 'PERSONAL' ELSE 'GROUP' END) = 'GROUP' AND NVL(wmp.USE_ACCOUNT_PROFILE, 'Y') = 'N' THEN wmp.PROFILE_IMAGE_PATH ELSE u.PROFILE_IMAGE_PATH END AS assigneeProfileImagePath, TO_CHAR(t.ACTUAL_STARTED_AT, 'YYYY-MM-DD HH24:MI:SS') AS actualStartDt, TO_CHAR(t.COMPLETED_AT, 'YYYY-MM-DD HH24:MI:SS') AS actualDoneDt, CASE WHEN NVL(t.STATUS, 'TODO') != 'DONE' AND t.END_AT IS NOT NULL AND t.END_AT < SYSDATE THEN 'Y' ELSE 'N' END AS delayedYn, CASE WHEN t.STATUS = 'DONE' AND t.END_AT IS NOT NULL AND t.COMPLETED_AT IS NOT NULL AND t.COMPLETED_AT > t.END_AT THEN 'Y' ELSE 'N' END AS delayedCompletedYn, CASE WHEN t.END_AT IS NULL THEN 0 WHEN t.STATUS = 'DONE' AND t.COMPLETED_AT IS NOT NULL THEN GREATEST(TRUNC(t.COMPLETED_AT) - TRUNC(t.END_AT), 0) WHEN NVL(t.STATUS, 'TODO') != 'DONE' AND t.END_AT < SYSDATE THEN GREATEST(TRUNC(SYSDATE) - TRUNC(t.END_AT), 0) ELSE 0 END AS delayedDays, 'N' AS isRecurring, NULL AS recurType, 1 AS recurInterval, NULL AS untilDt, NULL AS recurGroupId, NULL AS recurDays, NULL AS exceptionDateList, 'N' AS isLunar, NULL AS lunarMonth, NULL AS lunarDay, 'Asia/Seoul' AS timezone, 'N' AS reminderYn, NULL AS reminderMinutes FROM PROJECT_TASKS t JOIN PROJECTS p ON p.PROJ_ID = t.PROJ_ID LEFT JOIN WORKSPACES w ON w.WS_ID = p.WS_ID LEFT JOIN USERS u ON u.USER_ID = t.ASSIGNEE_ID LEFT JOIN WS_MEMBER_PROFILES wmp ON wmp.WS_ID = p.WS_ID AND wmp.USER_ID = t.ASSIGNEE_ID WHERE NVL(t.CALENDAR_VISIBLE_YN, 'Y') = 'Y' AND t.START_AT IS NOT NULL AND t.END_AT IS NOT NULL AND t.PROJ_ID IN ( SELECT PROJ_ID FROM PROJ_MEMBERS WHERE USER_ID = #{userId, jdbcType=NUMERIC} UNION SELECT PROJ_ID FROM PROJECTS WHERE LEADER_ID = #{userId, jdbcType=NUMERIC} )
AND t.PROJ_ID = #{projId, jdbcType=NUMERIC}
AND TRUNC(t.START_AT) <= TO_DATE(#{endDate}, 'YYYY-MM-DD') AND TRUNC(t.END_AT) >= TO_DATE(#{startDate}, 'YYYY-MM-DD') ORDER BY t.START_AT, t.END_AT, t.TASK_ID

SELECT COUNT(1)
  FROM EVENTS e
 WHERE e.EVENT_ID = #{eventId}
   AND (
        e.USER_ID = #{userId}
     OR EXISTS (
            SELECT 1
              FROM CONTENT_SHARES s
             WHERE s.CONTENT_TYPE = 'CALENDAR'
               AND s.CONTENT_ID = e.EVENT_ID
               AND s.ACTIVE_YN = 'Y'
               AND NVL(s.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED'
               AND UPPER(NVL(s.PERMISSION_TYPE, 'VIEW')) = 'EDIT'
               AND (s.EXPIRES_AT IS NULL OR s.EXPIRES_AT >= SYSDATE)
               AND (
                    (s.TARGET_TYPE = 'USER' AND s.TARGET_ID = #{userId})
                 OR (s.TARGET_TYPE = 'WS' AND EXISTS (
                        SELECT 1 FROM WS_MEMBERS wm
                         WHERE wm.WS_ID = s.TARGET_ID
                           AND wm.USER_ID = #{userId}
                    ))
                 OR (s.TARGET_TYPE = 'PROJ' AND EXISTS (
                        SELECT 1 FROM PROJ_MEMBERS pm
                         WHERE pm.PROJ_ID = s.TARGET_ID
                           AND pm.USER_ID = #{userId}
                    ))
               )
        )
     OR (NVL(e.ITEM_TYPE, 'PRIVATE') = 'WS' AND e.WS_ID IS NOT NULL AND (
            EXISTS (SELECT 1 FROM WORKSPACES w WHERE w.WS_ID = e.WS_ID AND w.OWNER_ID = #{userId})
         OR EXISTS (SELECT 1 FROM WS_MEMBERS wm2
                      WHERE wm2.WS_ID = e.WS_ID
                        AND wm2.USER_ID = #{userId}
                        AND UPPER(NVL(wm2.WS_ROLE, 'MEMBER')) IN ('ADMIN','OWNER','LEADER','MANAGER'))
        ))
     OR (NVL(e.ITEM_TYPE, 'PRIVATE') = 'PROJ' AND e.PROJ_ID IS NOT NULL AND (
            EXISTS (SELECT 1 FROM PROJECTS p WHERE p.PROJ_ID = e.PROJ_ID AND p.LEADER_ID = #{userId})
         OR EXISTS (SELECT 1 FROM PROJ_MEMBERS pm2
                      WHERE pm2.PROJ_ID = e.PROJ_ID
                        AND pm2.USER_ID = #{userId}
                        AND UPPER(NVL(pm2.PROJ_ROLE, 'MEMBER')) IN ('ADMIN','OWNER','LEADER','MANAGER','PM'))
        ))
   )

SELECT COUNT(1)
  FROM EVENTS e
 WHERE e.EVENT_ID = #{eventId}
   AND (
        e.USER_ID = #{userId}
     OR (NVL(e.ITEM_TYPE, 'PRIVATE') = 'WS' AND e.WS_ID IS NOT NULL AND (
            EXISTS (SELECT 1 FROM WORKSPACES w WHERE w.WS_ID = e.WS_ID AND w.OWNER_ID = #{userId})
         OR EXISTS (SELECT 1 FROM WS_MEMBERS wm
                      WHERE wm.WS_ID = e.WS_ID
                        AND wm.USER_ID = #{userId}
                        AND UPPER(NVL(wm.WS_ROLE, 'MEMBER')) IN ('ADMIN','OWNER','LEADER','MANAGER'))
        ))
     OR (NVL(e.ITEM_TYPE, 'PRIVATE') = 'PROJ' AND e.PROJ_ID IS NOT NULL AND (
            EXISTS (SELECT 1 FROM PROJECTS p WHERE p.PROJ_ID = e.PROJ_ID AND p.LEADER_ID = #{userId})
         OR EXISTS (SELECT 1 FROM PROJ_MEMBERS pm
                      WHERE pm.PROJ_ID = e.PROJ_ID
                        AND pm.USER_ID = #{userId}
                        AND UPPER(NVL(pm.PROJ_ROLE, 'MEMBER')) IN ('ADMIN','OWNER','LEADER','MANAGER','PM'))
        ))
   )

