INSERT INTO EVENT_ATTENDEES (EA_ID, EVENT_ID, USER_ID, ST_CODE)
SELECT SEQ_EA_ID.NEXTVAL, #{eventId}, #{userId}, 'WT'
  FROM DUAL
 WHERE #{eventId} IS NOT NULL
   AND #{userId} IS NOT NULL
   AND NOT EXISTS (
        SELECT 1 FROM EVENT_ATTENDEES
         WHERE EVENT_ID = #{eventId}
           AND USER_ID = #{userId}
   )

