mapper.update:
DECLARE
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'LOCATION_TEXT';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (LOCATION_TEXT VARCHAR2(500))'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'LOCATION_ADDRESS';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (LOCATION_ADDRESS VARCHAR2(700))'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'LOCATION_LAT';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (LOCATION_LAT NUMBER(15,10))'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'LOCATION_LNG';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (LOCATION_LNG NUMBER(15,10))'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'LOCATION_PLACE_ID';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (LOCATION_PLACE_ID VARCHAR2(200))'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'DESCRIPTION_TEXT';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (DESCRIPTION_TEXT VARCHAR2(4000))'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'TIMEZONE_ID';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (TIMEZONE_ID VARCHAR2(50) DEFAULT ''Asia/Seoul'')'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'REMINDER_YN';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (REMINDER_YN CHAR(1) DEFAULT ''N'' NOT NULL)'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'REMINDER_MINUTES';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (REMINDER_MINUTES NUMBER(10))'; END IF;

    /* 프로젝트 업무/간트에서 쓰는 컬럼이 없는 DB에서도 월간 캘린더 조회가 500으로 죽지 않게 보강 */
    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'STATUS';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (STATUS VARCHAR2(30) DEFAULT ''TODO'')'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'START_TIME_SLOT';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (START_TIME_SLOT VARCHAR2(20))'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'END_TIME_SLOT';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (END_TIME_SLOT VARCHAR2(20))'; END IF;
END;

