(
    (s.TARGET_TYPE = 'USER' AND s.TARGET_ID = #{userId})
 OR (s.TARGET_TYPE = 'WS' AND EXISTS (
        SELECT 1 FROM WS_MEMBERS wm
         WHERE wm.WS_ID = s.TARGET_ID
           AND wm.USER_ID = #{userId}
    ))
 OR (s.TARGET_TYPE = 'PROJ' AND EXISTS (
        SELECT 1 FROM PROJ_MEMBERS pm
         WHERE pm.PROJ_ID = s.TARGET_ID
           AND pm.USER_ID = #{userId}
    ))
)

(
    e.USER_ID = #{userId}
 OR (e.ITEM_TYPE = 'WS' AND EXISTS (
        SELECT 1
          FROM WORKSPACES w
          LEFT JOIN WS_MEMBERS wm ON wm.WS_ID = w.WS_ID AND wm.USER_ID = #{userId}
         WHERE w.WS_ID = e.WS_ID
           AND (w.OWNER_ID = #{userId} OR UPPER(NVL(wm.WS_ROLE, 'MEMBER')) = 'ADMIN')
    ))
 OR (e.ITEM_TYPE IN ('PROJ', 'TASK', 'SCHEDULE') AND EXISTS (
        SELECT 1
          FROM PROJECTS p
          LEFT JOIN PROJ_MEMBERS pm ON pm.PROJ_ID = p.PROJ_ID AND pm.USER_ID = #{userId}
         WHERE p.PROJ_ID = e.PROJ_ID
           AND (p.LEADER_ID = #{userId} OR UPPER(NVL(pm.PROJ_ROLE, 'MEMBER')) IN ('ADMIN', 'LEADER', 'OWNER', 'PM'))
    ))
)

mapper.update:
DECLARE
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'TIMEZONE_ID';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (TIMEZONE_ID VARCHAR2(50) DEFAULT ''Asia/Seoul'')'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'REMINDER_YN';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (REMINDER_YN CHAR(1) DEFAULT ''N'' NOT NULL)'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'REMINDER_MINUTES';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (REMINDER_MINUTES NUMBER)'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'REMINDER_SENT_YN';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (REMINDER_SENT_YN CHAR(1) DEFAULT ''N'' NOT NULL)'; END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'EVENTS' AND COLUMN_NAME = 'REMINDER_SENT_AT';
    IF v_count = 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (REMINDER_SENT_AT DATE)'; END IF;
END;
